"""Batch lead-lag analysis for distributional canary collapse experiments.

Reads all_metrics.json from an experiment directory, runs 5-method lead-lag
analysis on all canary-diversity pairs, computes K>=4 consensus, and optionally
runs full MMCT if null directories are provided.

Usage:
    python batch_analysis.py --exp_dir results/alpha_sweep/a010_s43_bf16
    python batch_analysis.py --exp_dir results/alpha_sweep/a010_s43_bf16 \
        --null_dirs results/alpha_sweep/a000_s42 results/alpha_sweep/a000_s43

Input:  {exp_dir}/all_metrics.json
Output: {exp_dir}/analysis_results.json (or --output path)

Dependencies: numpy, scipy, statsmodels
"""

import argparse
import json
import os
import sys
import traceback
import numpy as np
from scipy import stats
from statsmodels.tsa.stattools import adfuller

N_PERM = 5000
ALPHA_SIG = 0.05

CANARIES = ["token_entropy", "ece"]
DOWNSTREAMS = ["distinct_1", "distinct_2", "distinct_3", "mauve"]

HIGHER_IS_WORSE = {"ece", "perplexity"}
LOWER_IS_WORSE = {"token_entropy", "distinct_1", "distinct_2", "distinct_3", "mauve"}

ALL_METRICS = ["token_entropy", "ece", "perplexity", "distinct_1", "distinct_2",
               "distinct_3", "effective_rank", "mauve"]


def load_series(data_dir):
    path = os.path.join(data_dir, "all_metrics.json")
    with open(path) as f:
        data = json.load(f)
    data.sort(key=lambda x: x["generation"])
    out = {}
    for k in ALL_METRICS:
        vals = []
        for d in data:
            v = d.get(k)
            vals.append(v if v is not None else np.nan)
        out[k] = np.array(vals, dtype=float)
    return out, len(data)


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def compute_drift(series_dict, n_gens):
    drift = {}
    for k in ALL_METRICS:
        s = series_dict.get(k)
        if s is None or len(s) < 2:
            drift[k] = None
            continue
        v0, v_last = s[0], s[-1]
        if abs(v0) < 1e-12:
            drift[k] = None
        else:
            drift[k] = round(float((v_last - v0) / abs(v0) * 100), 2)
    return drift


def bh_fdr(p_values, alpha=0.05):
    pv = np.array(p_values, dtype=float)
    n = len(pv)
    valid = ~np.isnan(pv)
    adjusted = np.full(n, np.nan)
    if valid.sum() == 0:
        return adjusted.tolist(), [False] * n
    idx = np.where(valid)[0]
    p_valid = pv[idx]
    sorted_idx = np.argsort(p_valid)
    ranks = np.empty_like(sorted_idx)
    ranks[sorted_idx] = np.arange(1, len(p_valid) + 1)
    m = len(p_valid)
    adj = p_valid * m / ranks
    adj_sorted = adj[sorted_idx].copy()
    for i in range(m - 2, -1, -1):
        adj_sorted[i] = min(adj_sorted[i], adj_sorted[i + 1])
    adj_sorted = np.minimum(adj_sorted, 1.0)
    adj_final = np.empty(m)
    adj_final[sorted_idx] = adj_sorted
    for i, ix in enumerate(idx):
        adjusted[ix] = adj_final[i]
    significant = [(adjusted[i] < alpha if not np.isnan(adjusted[i]) else False) for i in range(n)]
    return adjusted.tolist(), significant


# ── Method 1: Naive cross-correlation ──

def naive_xcorr(c, d, cn, dn, max_lag=5):
    x, y = orient(c, cn), orient(d, dn)
    n = len(x)
    if np.any(np.isnan(x)) or np.any(np.isnan(y)):
        return {"method": "naive_xcorr", "peak_lag": None, "r": None,
                "p_value": None, "significant": False, "note": "NaN in data"}
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
            a, b = x[lag:], y[:n - lag]
        else:
            a, b = x[:n + lag], y[-lag:]
        if len(a) < 4:
            continue
        if np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {
        "method": "naive_xcorr",
        "peak_lag": int(best_lag),
        "r": round(float(best_r), 4),
        "p_value": round(float(best_p), 6),
        "significant": bool(best_p < ALPHA_SIG),
    }


# ── Method 2: Differenced cross-correlation ──

def diff_xcorr(c, d, cn, dn, max_lag=5):
    x, y = orient(c, cn), orient(d, dn)
    if np.any(np.isnan(x)) or np.any(np.isnan(y)):
        return {"method": "diff_xcorr", "peak_lag": None, "r": None,
                "p_value": None, "significant": False, "note": "NaN in data"}
    dx, dy = np.diff(x), np.diff(y)
    n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
            a, b = dx[lag:], dy[:n - lag]
        else:
            a, b = dx[:n + lag], dy[-lag:]
        if len(a) < 4:
            continue
        if np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {
        "method": "diff_xcorr",
        "peak_lag": int(best_lag),
        "r": round(float(best_r), 4),
        "p_value": round(float(best_p), 6),
        "significant": bool(best_p < ALPHA_SIG),
    }


# ── Method 3: Threshold onset detection ──

def threshold_onset(c, d, cn, dn, sigma_mult=3):
    x, y = orient(c, cn), orient(d, dn)
    if np.any(np.isnan(x)) or np.any(np.isnan(y)):
        return {"method": "threshold_onset", "onset_canary": None,
                "onset_downstream": None, "lead_time": None, "significant": False,
                "note": "NaN in data"}
    gen0_c, gen0_d = x[0], y[0]
    std_c = np.std(np.diff(x)) if len(x) > 1 else 1e-12
    std_d = np.std(np.diff(y)) if len(y) > 1 else 1e-12
    if std_c < 1e-12:
        std_c = abs(gen0_c) * 0.01 if abs(gen0_c) > 1e-12 else 1e-6
    if std_d < 1e-12:
        std_d = abs(gen0_d) * 0.01 if abs(gen0_d) > 1e-12 else 1e-6
    thresh_c = gen0_c + sigma_mult * std_c
    thresh_d = gen0_d + sigma_mult * std_d
    onset_c, onset_d = None, None
    for i in range(1, len(x)):
        if onset_c is None and x[i] > thresh_c:
            onset_c = i
        if onset_d is None and y[i] > thresh_d:
            onset_d = i
    if onset_c is not None and onset_d is not None:
        lead = onset_d - onset_c
        significant = lead > 0
    elif onset_c is not None and onset_d is None:
        lead = len(x) - onset_c
        significant = True
    else:
        lead = 0
        significant = False
    return {
        "method": "threshold_onset",
        "onset_canary": onset_c,
        "onset_downstream": onset_d,
        "lead_time": int(lead) if lead is not None else None,
        "significant": significant,
    }


# ── Method 4: Permutation Granger ──

def _build_lag_matrix(y, x, max_lag):
    T = len(y)
    n = T - max_lag
    Y = y[max_lag:]
    cols_r = [np.ones(n)]
    for lag in range(1, max_lag + 1):
        cols_r.append(y[max_lag - lag: T - lag])
    cols_u = list(cols_r)
    for lag in range(1, max_lag + 1):
        cols_u.append(x[max_lag - lag: T - lag])
    return Y, np.column_stack(cols_r), np.column_stack(cols_u)


def _granger_f_stat(y, x, max_lag):
    Y, X_r, X_u = _build_lag_matrix(y, x, max_lag)
    n = len(Y)
    q = max_lag
    try:
        beta_r = np.linalg.lstsq(X_r, Y, rcond=None)[0]
        beta_u = np.linalg.lstsq(X_u, Y, rcond=None)[0]
    except np.linalg.LinAlgError:
        return np.nan
    rss_r = np.sum((Y - X_r @ beta_r) ** 2)
    rss_u = np.sum((Y - X_u @ beta_u) ** 2)
    k_u = X_u.shape[1]
    df_resid = n - k_u
    if df_resid <= 0 or rss_u < 1e-15:
        return np.nan
    return ((rss_r - rss_u) / q) / (rss_u / df_resid)


def perm_granger(x, y, max_lag=1, n_perm=N_PERM, seed=42, difference=True):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if np.any(np.isnan(x)) or np.any(np.isnan(y)):
        return {"method": "perm_granger", "f_stat": None, "p_value": None,
                "significant": False, "note": "NaN in data"}
    if difference:
        x, y = np.diff(x), np.diff(y)
    T = len(x)
    if T <= max_lag + 2:
        return {"method": "perm_granger", "f_stat": None, "p_value": None,
                "significant": False, "note": f"T={T} too short"}
    f_obs = _granger_f_stat(y, x, max_lag)
    if np.isnan(f_obs):
        return {"method": "perm_granger", "f_stat": None, "p_value": None,
                "significant": False, "note": "F-stat failed"}
    rng = np.random.default_rng(seed)
    null_f = np.empty(n_perm)
    for i in range(n_perm):
        null_f[i] = _granger_f_stat(y, rng.permutation(x), max_lag)
    valid = null_f[~np.isnan(null_f)]
    if len(valid) == 0:
        return {"method": "perm_granger", "f_stat": round(float(f_obs), 4),
                "p_value": None, "significant": False}
    p = (np.sum(valid >= f_obs) + 1) / (len(valid) + 1)
    return {
        "method": "perm_granger",
        "f_stat": round(float(f_obs), 4),
        "p_value": round(float(p), 6),
        "significant": bool(p < ALPHA_SIG),
    }


# ── Method 5: Toda-Yamamoto Granger ──

def _determine_d_max(series, max_d=2, alpha=0.05):
    for d in range(max_d + 1):
        try:
            result = adfuller(series, maxlag=min(3, len(series) // 3 - 1),
                              regression="ct", autolag="AIC")
            if result[1] < alpha:
                return d
            series = np.diff(series)
        except Exception:
            return d
    return max_d


def ty_granger(c, d, cn, dn, max_lag=1):
    x, y = orient(c, cn), orient(d, dn)
    if np.any(np.isnan(x)) or np.any(np.isnan(y)):
        return {"method": "ty_granger", "chi2": None, "p_value": None,
                "significant": False, "note": "NaN in data"}
    d_max = max(_determine_d_max(x), _determine_d_max(y))
    p_total = max_lag + d_max
    T = len(x)
    n = T - p_total
    if n <= p_total + 2:
        return {"method": "ty_granger", "chi2": None, "p_value": None,
                "significant": False, "d_max": int(d_max),
                "note": f"T={T} too short for d_max={d_max}, p={p_total}"}
    Y = y[p_total:]
    cols_r = [np.ones(n)]
    for lag in range(1, p_total + 1):
        cols_r.append(y[p_total - lag: T - lag])
    for lag in range(max_lag + 1, p_total + 1):
        cols_r.append(x[p_total - lag: T - lag])
    cols_u = list(cols_r)
    for lag in range(1, max_lag + 1):
        cols_u.append(x[p_total - lag: T - lag])
    X_r = np.column_stack(cols_r)
    X_u = np.column_stack(cols_u)
    try:
        beta_r = np.linalg.lstsq(X_r, Y, rcond=None)[0]
        beta_u = np.linalg.lstsq(X_u, Y, rcond=None)[0]
    except np.linalg.LinAlgError:
        return {"method": "ty_granger", "chi2": None, "p_value": None,
                "significant": False, "note": "lstsq failed"}
    rss_r = np.sum((Y - X_r @ beta_r) ** 2)
    rss_u = np.sum((Y - X_u @ beta_u) ** 2)
    df_resid = n - X_u.shape[1]
    if df_resid <= 0 or rss_u < 1e-15:
        return {"method": "ty_granger", "chi2": None, "p_value": None,
                "significant": False, "note": f"df_resid={df_resid}"}
    q = max_lag
    W = n * (rss_r - rss_u) / rss_u
    p_val = 1.0 - stats.chi2.cdf(W, q)
    return {
        "method": "ty_granger",
        "chi2": round(float(W), 4),
        "p_value": round(float(p_val), 6),
        "d_max": int(d_max),
        "df_resid": int(df_resid),
        "significant": bool(p_val < ALPHA_SIG),
    }


# ── Run all 5 methods on one pair ──

def run_pair(series, cn, dn):
    c, d = series[cn], series[dn]
    results = {}
    results["naive_xcorr"] = naive_xcorr(c, d, cn, dn)
    results["diff_xcorr"] = diff_xcorr(c, d, cn, dn)
    results["threshold_onset"] = threshold_onset(c, d, cn, dn)
    # forward: canary -> downstream (x=canary causes y=downstream)
    results["perm_granger_fwd"] = perm_granger(orient(c, cn), orient(d, dn),
                                                seed=42, difference=True)
    results["perm_granger_fwd"]["direction"] = "forward"
    # reverse: downstream -> canary
    results["perm_granger_rev"] = perm_granger(orient(d, dn), orient(c, cn),
                                                seed=42, difference=True)
    results["perm_granger_rev"]["direction"] = "reverse"
    results["ty_granger"] = ty_granger(c, d, cn, dn)
    return results


# ── Apply BH FDR across 8 pairs ──

def apply_fdr_correction(all_pair_results):
    for method_key, p_key in [("diff_xcorr", "p_value"),
                               ("perm_granger_fwd", "p_value"),
                               ("perm_granger_rev", "p_value")]:
        pvals = []
        for pr in all_pair_results:
            r = pr["results"].get(method_key, {})
            p = r.get(p_key)
            pvals.append(p if p is not None else np.nan)
        adj, sig = bh_fdr(pvals)
        for i, pr in enumerate(all_pair_results):
            r = pr["results"].get(method_key, {})
            r["p_fdr"] = round(adj[i], 6) if not np.isnan(adj[i]) else None
            r["significant_fdr"] = sig[i]


# ── Consensus counting ──

def compute_consensus(pair_result):
    r = pair_result["results"]
    votes = 0
    methods_sig = []
    if r["naive_xcorr"].get("significant", False):
        votes += 1; methods_sig.append("naive")
    if r["diff_xcorr"].get("significant_fdr", r["diff_xcorr"].get("significant", False)):
        votes += 1; methods_sig.append("diff")
    if r["threshold_onset"].get("significant", False):
        votes += 1; methods_sig.append("thresh")
    if r["perm_granger_fwd"].get("significant_fdr", r["perm_granger_fwd"].get("significant", False)):
        votes += 1; methods_sig.append("pg_fwd")
    if r["ty_granger"].get("significant", False):
        votes += 1; methods_sig.append("ty")
    return votes, methods_sig


# ── MMCT (full, if null dirs available) ──

def run_mmct_full(exp_dir, null_dirs):
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from mmct.null_distribution import NullDistribution
    from mmct.consensus_test import MMCT
    from mmct.methods import METRIC_PAIRS as MMCT_PAIRS

    null_dist = NullDistribution(null_dirs, n_bootstrap=10000, seed=42)
    mmct = MMCT(null_dist, weighted=True, bidirectional=False, alpha=0.05)

    n_sig = 0
    n_total = 0
    pair_results = []
    for canary, downstream in MMCT_PAIRS:
        try:
            result = mmct.test_from_precomputed(exp_dir, canary, downstream)
            r = result.to_dict()
            pair_results.append(r)
            n_total += 1
            if r["significant"]:
                n_sig += 1
        except Exception:
            n_total += 1
    detection_rate = n_sig / n_total if n_total > 0 else 0.0
    return {
        "mode": "weighted_pair_forward",
        "detection_rate": round(detection_rate, 4),
        "sig": n_sig,
        "total": n_total,
        "pair_results": pair_results,
    }


# ── Main ──

def analyze(exp_dir, output_path=None, null_dirs=None):
    print(f"Loading data from {exp_dir}")
    series, n_gens = load_series(exp_dir)
    print(f"  {n_gens} generations loaded")

    # 1. Drift
    print("Computing drift...")
    drift = compute_drift(series, n_gens)

    # 2. Lead-lag (5 methods, 8 pairs)
    print("Running 5-method lead-lag analysis...")
    all_pairs = []
    for cn in CANARIES:
        for dn in DOWNSTREAMS:
            try:
                r = run_pair(series, cn, dn)
                all_pairs.append({"canary": cn, "downstream": dn, "results": r})
            except Exception as e:
                print(f"  WARN: {cn}->{dn} failed: {e}")
                all_pairs.append({"canary": cn, "downstream": dn,
                                  "results": {}, "error": str(e)})

    apply_fdr_correction(all_pairs)

    # Count summary
    naive_fwd = sum(1 for p in all_pairs if p["results"].get("naive_xcorr", {}).get("significant", False))
    diff_fwd = sum(1 for p in all_pairs if p["results"].get("diff_xcorr", {}).get("significant_fdr",
                    p["results"].get("diff_xcorr", {}).get("significant", False)))
    thresh_fwd = sum(1 for p in all_pairs if p["results"].get("threshold_onset", {}).get("significant", False))
    pg_fwd = sum(1 for p in all_pairs if p["results"].get("perm_granger_fwd", {}).get("significant_fdr",
                  p["results"].get("perm_granger_fwd", {}).get("significant", False)))
    pg_rev = sum(1 for p in all_pairs if p["results"].get("perm_granger_rev", {}).get("significant_fdr",
                  p["results"].get("perm_granger_rev", {}).get("significant", False)))
    ty_sig = sum(1 for p in all_pairs if p["results"].get("ty_granger", {}).get("significant", False))

    consensus_counts = []
    for p in all_pairs:
        votes, methods = compute_consensus(p)
        consensus_counts.append({"pair": f"{p['canary']}->{p['downstream']}",
                                  "votes": votes, "methods": methods})
    k4 = sum(1 for c in consensus_counts if c["votes"] >= 4)
    total = len(all_pairs)

    lead_lag = {
        "naive_xcorr": {"forward": naive_fwd, "total": total},
        "diff_xcorr": {"forward": diff_fwd, "total": total},
        "threshold_onset": {"forward": thresh_fwd, "total": total},
        "perm_granger_fwd": {"sig": pg_fwd, "total": total},
        "perm_granger_rev": {"sig": pg_rev, "total": total},
        "ty_granger": {"sig": ty_sig, "total": total},
        "consensus_k4": {"sig": k4, "total": total},
    }

    # 3. MMCT
    mmct_result = None
    if null_dirs:
        print("Running full MMCT (weighted_pair_forward)...")
        try:
            # MMCT requires pre-computed 5method_leadlag.json
            # First save the lead-lag results in the format MMCT expects
            analysis_dir = os.path.join(exp_dir, "analysis")
            os.makedirs(analysis_dir, exist_ok=True)
            _save_5method_format(all_pairs, n_gens, exp_dir, analysis_dir)
            mmct_result = run_mmct_full(exp_dir, null_dirs)
        except Exception as e:
            print(f"  MMCT failed: {e}")
            traceback.print_exc()
            mmct_result = {"mode": "weighted_pair_forward", "error": str(e)}
    else:
        print("No null_dirs provided, using simple K>=4 consensus as MMCT proxy")
        mmct_result = {
            "mode": "weighted_pair_forward",
            "detection_rate": round(k4 / total, 4) if total > 0 else 0.0,
            "note": "simple_consensus_k4 (no null distribution)",
        }

    # 4. Build output
    output = {
        "exp_dir": exp_dir,
        "n_generations": n_gens,
        "drift_pct": drift,
        "lead_lag": lead_lag,
        "mmct": mmct_result,
        "consensus_detail": consensus_counts,
        "pair_details": _clean(all_pairs),
    }

    if output_path is None:
        output_path = os.path.join(exp_dir, "analysis_results.json")
    os.makedirs(os.path.dirname(output_path) or ".", exist_ok=True)
    with open(output_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nSaved: {output_path}")

    # Print summary
    print(f"\n{'='*60}")
    print(f"SUMMARY: {exp_dir}")
    print(f"{'='*60}")
    print(f"Generations: {n_gens}")
    print(f"\nDrift (gen0->gen{n_gens-1}):")
    for k, v in drift.items():
        if v is not None:
            print(f"  {k:20s}: {v:+.2f}%")
    print(f"\nLead-lag (forward significant / total):")
    for method, counts in lead_lag.items():
        key = "forward" if "forward" in counts else "sig"
        print(f"  {method:20s}: {counts[key]}/{counts['total']}")
    print(f"\nMMCT: {mmct_result.get('mode', 'N/A')}, "
          f"detection_rate={mmct_result.get('detection_rate', 'N/A')}")

    return output


def _save_5method_format(all_pairs, n_gens, exp_dir, analysis_dir):
    """Save lead-lag results in the format expected by MMCT module."""
    pairs_out = []
    for p in all_pairs:
        r = p["results"]
        pair_entry = {
            "canary": p["canary"],
            "downstream": p["downstream"],
            "forward": {},
            "reverse": {},
        }
        for method in ["naive_xcorr", "diff_xcorr", "threshold_onset", "ty_granger"]:
            if method in r:
                pair_entry["forward"][method] = r[method]
        if "perm_granger_fwd" in r:
            pair_entry["forward"]["perm_granger"] = r["perm_granger_fwd"]
        if "perm_granger_rev" in r:
            pair_entry["reverse"]["perm_granger"] = r["perm_granger_rev"]
        pairs_out.append(pair_entry)

    output = {
        "n_generations": n_gens,
        "data_dir": exp_dir,
        "methods": ["naive_xcorr", "diff_xcorr", "threshold_onset",
                     "perm_granger", "ty_granger"],
        "pairs": pairs_out,
    }
    path = os.path.join(analysis_dir, "5method_leadlag.json")
    with open(path, "w") as f:
        json.dump(_clean(output), f, indent=2)


def _clean(obj):
    if isinstance(obj, (np.floating, np.float64, np.float32)):
        return float(obj)
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, np.bool_):
        return bool(obj)
    if isinstance(obj, dict):
        return {k: _clean(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_clean(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return [_clean(v) for v in obj.tolist()]
    return obj


